' ?>" role="img" aria-label="<?= (int) $c['duePct'] ?>%"><i style="width:<?= (int) $c['duePct'] ?>%"></i></div><div class="ft">Paid <?= h($c['paid']) ?> to date<?= $c['points'] !== null ? ' · ' . sl_num($c['points']) . ' points' : '' ?></div></a></div>
